import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const TABS = ["Нүүр", "Сагс", "Профайл"];

function App() {
  return (
    <View style={styles.container}>
      <View style={styles.body}><Text>Агуулга</Text></View>
      <View nativeID="tabbar" style={styles.tabbar}>
        {/* энд бичнэ үү: TABS-г таб болгон буулга (testID="tab") */}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  body: { flex: 1, alignItems: "center", justifyContent: "center" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);

import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const TABS = ["Нүүр", "Сагс", "Профайл"];

function App() {
  return (
    <View style={styles.container}>
      <View style={styles.body}><Text>Агуулга</Text></View>
      <View nativeID="tabbar" style={styles.tabbar}>
        {TABS.map((t) => (
          <View key={t} testID="tab" style={styles.tab}>
            <Text style={styles.tabText}>{t}</Text>
          </View>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  body: { flex: 1, alignItems: "center", justifyContent: "center" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);
